import type { AppConfig } from "awatif/templates";

// Cornerstone Pressure Washing building section: a 70'-0" clear-span steel
// truss (HSS chords, 4:12 roof pitch) on W16x67 columns, modelled in the XZ
// work plane in metres. z = 0 is the floor; column bases sit on the piers at
// top of footing, 2'-0" above the floor.

const ft = 0.3048;

const span = 70 * ft; // grid A to grid B
const pitch = 4 / 12;
const zBase = 2 * ft; // T.O.F.
const zBottomChord = zBase + (16 + 8 / 12) * ft; // T.O.F. to U/S of truss 16'-8"
const zColumnTop = zBase + (19 + 6.75 / 12) * ft; // height of column 19'-6 3/4"
const leftOverhang = 0.5 * ft; // 6"
const rightOverhang = 5 * ft; // 5'-0"
const halfPanels = 16; // 8 Warren web panels per half truss
const step = span / (2 * halfPanels);

// Height of the parallel chords above their eaves level at position x
const rise = (x: number) => Math.min(x, span - x) * pitch;

const points: [number, number, number][] = [];
const lines: [number, number][] = [];
const addPoint = (x: number, z: number) => points.push([x, 0, z]);
const addLine = (group: number[], a: number, b: number) =>
  group.push(lines.push([a, b]));

const columns: number[] = [];
const topChord: number[] = [];
const bottomChord: number[] = [];
const webs: number[] = [];

// Panel points along the span: even k on the bottom chord, odd k on the top
// chord, plus top chord points over both columns and at the ridge
const top = new Map<number, number>();
const bottom = new Map<number, number>();
for (let k = 0; k <= 2 * halfPanels; k++) {
  const x = k * step;
  if (k % 2 === 0) bottom.set(k, addPoint(x, zBottomChord + rise(x)));
  if (k % 2 === 1 || k === 0 || k === halfPanels || k === 2 * halfPanels)
    top.set(k, addPoint(x, zColumnTop + rise(x)));
}
const last = 2 * halfPanels;
const baseA = addPoint(0, zBase);
const baseB = addPoint(span, zBase);
const eaveA = addPoint(-leftOverhang, zColumnTop - leftOverhang * pitch);
const eaveB = addPoint(span + rightOverhang, zColumnTop - rightOverhang * pitch);

// Columns: base -> truss bottom chord -> truss top chord
addLine(columns, baseA, bottom.get(0)!);
addLine(columns, bottom.get(0)!, top.get(0)!);
addLine(columns, baseB, bottom.get(last)!);
addLine(columns, bottom.get(last)!, top.get(last)!);

// Top chord including the overhangs
const topIds = [...top.keys()].sort((a, b) => a - b).map((k) => top.get(k)!);
[eaveA, ...topIds, eaveB].forEach((p, i, all) => {
  if (i > 0) addLine(topChord, all[i - 1], p);
});

// Bottom chord
const bottomIds = [...bottom.keys()].sort((a, b) => a - b).map((k) => bottom.get(k)!);
bottomIds.forEach((p, i) => {
  if (i > 0) addLine(bottomChord, bottomIds[i - 1], p);
});

// Warren diagonals and the ridge vertical
for (let k = 0; k < last; k++) {
  const from = k % 2 === 0 ? bottom.get(k)! : top.get(k)!;
  const to = k % 2 === 0 ? top.get(k + 1)! : bottom.get(k + 1)!;
  addLine(webs, from, to);
}
addLine(webs, bottom.get(halfPanels)!, top.get(halfPanels)!);

export const cornerstoneTruss: AppConfig = {
  points,
  lines,

  gridLines: [
    {
      name: "Section Grid",
      templateId: "grid-system",
      geometry: [],
      params: {
        x: [
          { id: "A", ordinate: 0, visible: true, bubble: "end" },
          { id: "Ridge", ordinate: span / 2, visible: true, bubble: "end" },
          { id: "B", ordinate: span, visible: true, bubble: "end" },
        ],
        y: [{ id: "1", ordinate: 0, visible: true, bubble: "start" }],
        z: [
          { id: "Floor", ordinate: 0, visible: true, bubble: "end" },
          { id: "T.O.F.", ordinate: zBase, visible: true, bubble: "end" },
          { id: "U/S Truss", ordinate: zBottomChord, visible: true, bubble: "end" },
          { id: "Column Top", ordinate: zColumnTop, visible: true, bubble: "end" },
          {
            id: "Ridge",
            ordinate: zColumnTop + rise(span / 2),
            visible: true,
            bubble: "end",
          },
        ],
      },
    },
  ],

  supports: [
    {
      name: "Fixed Column Bases",
