  xRange(k).forEach((i) =>
    ys.forEach((y, j) => {
      points.push([xs[i], y, z]);
      pointIds.set(`${i},${j},${k}`, points.length);
    }),
  ),
);
const p = (i: number, j: number, k: number) => pointIds.get(`${i},${j},${k}`)!;

const lines: [number, number][] = [];
const columns: number[] = [];
const beams: number[] = [];
const braces: number[] = [];
const addLine = (group: number[], a: number, b: number) => {
  lines.push([a, b]);
  group.push(lines.length);
};

for (let k = 1; k < zs.length; k++) {
  const range = xRange(k);

  // Columns from the level below
  range.forEach((i) => ys.forEach((_, j) => addLine(columns, p(i, j, k - 1), p(i, j, k))));

  // E-W beams
  ys.forEach((_, j) =>
    range.slice(1).forEach((i) => addLine(beams, p(i - 1, j, k), p(i, j, k))),
  );

  // N-S beams
  range.forEach((i) =>
    ys.slice(1).forEach((_, j) => addLine(beams, p(i, j, k), p(i, j + 1, k))),
  );

  // CBF braces on grids D and A: from the base of grids 2 and 4 up to grid 3
  [0, 3].forEach((j) => {
    addLine(braces, p(1, j, k - 1), p(2, j, k));
    addLine(braces, p(3, j, k - 1), p(2, j, k));
  });
}

